#include "2mm.h"


void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{


    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

  int i, j, k;


  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
	tmp[i][j] = 0.0;
	for (k = 0; k < nk; ++k)
	  tmp[i][j] += alpha * A[i][k] * B[k][j];
      }
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
	D[i][j] *= beta;
	for (k = 0; k < nj; ++k)
	  D[i][j] += tmp[i][k] * C[k][j];
      }

}

cases.reply:
Looking at this benchmark, I need to implement a 2mm kernel (two matrix multiplications) with HLS optimizations. The key insight from `hls-chained-gemm-local-reuse` and `hls-gemm-static-nest-flatten-and-k-partition` skills is:

1. Stage all arrays locally to avoid repeated m_axi access
2. Keep the intermediate `tmp` in local memory (chained through phases)
3. Partition locals on the reduction (k) dimension
4. Pipeline the (i,j) nest with k fully unrolled and LOOP_FLATTEN
5. Store tmp and D back to global memory once

The problem dimensions are: NI=40, NJ=50, NK=70, NL=80 — all small enough for full local staging and complete k-partition.

**Phase 1:** `tmp[NI][NJ] = alpha * A[NI][NK] * B[NK][NJ]` — reduce over k=0..NK-1  
**Phase 2:** `D[NI][NL] = beta*D + tmp[NI][NJ] * C[NJ][NL]` — reduce over k=0..NJ-1

I'll partition `A` on dim=2 (NK), `B` on dim=1 (NK), `tmp` on dim=2 (NJ), `C` on dim=1 (NJ) to enable fully unrolled k-reductions with II=1 flattened (i,j) pipelines.

```cpp
#include "2mm.h"

extern "C" {

void kernel_2mm(
    double alpha,
    double beta,
    double tmp[NI + 0][NJ + 0],
    double A[NI + 0][NK + 0],
    double B[NK + 0][NJ + 0],
    double C[NJ + 0][NL + 0],
    double D[NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A      offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B      offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C      offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D      offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=B      bundle=control
#pragma HLS INTERFACE s_axilite port=C      bundle=control
#pragma HLS INTERFACE s_axilite port=D      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for all arrays
    double local_A[NI][NK];
    double local_B[NK][NJ];
    double local_C[NJ][NL];
    double local_D[NI][NL];
    double local_tmp[NI][NJ];

    // Partition on reduction dimensions for parallel access
    // Phase 1 reduction over k (dim NK): partition A dim=2, B dim=1
    // Phase 2 reduction over k (dim NJ): partition tmp dim=2, C dim=1
#pragma HLS ARRAY_PARTITION variable=local_A   complete dim=2
#pragma HLS ARRAY_PARTITION variable=local_B   complete dim=1
#pragma HLS ARRAY_PARTITION variable=local_tmp complete dim=2
#pragma HLS ARRAY_PARTITION variable=local_C   complete dim=1

    // Load A
    load_A:
    for (int i = 0; i < NI; i++) {
        for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            local_A[i][k] = A[i][k];
        }
    }

    // Load B
    load_B:
    for (int k = 0; k < NK; k++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            local_B[k][j] = B[k][j];
        }
    }

    // Load C
    load_C:
    for (int j = 0; j < NJ; j++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            local_C[j][l] = C[j][l];
        }
    }

    // Load D
    load_D:
    for (int i = 0; i < NI; i++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            local_D[i][l] = D[i][l];
        }
    }

    // Phase 1: local_tmp = alpha * local_A * local_B
    // Flatten (i,j) pipeline with k fully unrolled
    compute_tmp:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
            double sum = 0.0;
            for (int k = 0; k < NK; k++) {
#pragma HLS UNROLL
                sum += alpha * local_A[i][k] * local_B[k][j];
            }
            local_tmp[i][j] = sum;
        }
    }

    // Phase 2: local_D = beta * local_D + local_tmp * local_C
    // Flatten (i,l) pipeline with j (NJ) fully unrolled
    compute_D:
    for (int i = 0; i < NI; i++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
            double sum = local_D[i][l] * beta;
            for (int k = 0; k < NJ; k++) {
#pragma HLS UNROLL
                sum += local_tmp[i][k] * local_C[k][l];
            }
            local_D[i][l] = sum;
        }
    }

    // Store tmp back to global memory
    store_tmp:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            tmp[i][j] = local_tmp[i][j];
        }
    }

    // Store D back to global memory
    store_D:
    for (int i = 0; i < NI; i++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            D[i][l] = local_D[i][l];
        }
    }
}

} // extern "C"
