#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    // Local staging buffers (B is shared/read-only; A and C are double-buffered)
    static double B_local[NK][NJ];
    static double C_local_1[NJ];
    static double C_local_2[NJ];
    static double A_local_1[NK];
    static double A_local_2[NK];
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=2 dim=2
#pragma HLS ARRAY_PARTITION variable=C_local_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=C_local_2 cyclic factor=2 dim=1

    int i, j, k;

    // Stage the entire B matrix into local BRAM with contiguous bursts
  LOAD_B_K:
    for (k = 0; k < nk; k++) {
#pragma HLS LOOP_TRIPCOUNT min=NK max=NK
    LOAD_B_J:
      for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
        B_local[k][j] = B[k][j];
      }
    }

    // Double-buffered pipeline over rows.
    // Iteration schedule (N = ni total rows):
    //   iter 0    : load(row 0) -> buf A ; compute(skip)     ; store(skip)
    //   iter 1    : load(row 1) -> buf B ; compute(row 0) A  ; store(skip)
    //   iter t    : load(row t)          ; compute(row t-1)  ; store(row t-2)
    //   iter N    : load(skip)           ; compute(row N-1)  ; store(row N-2)
    //   iter N+1  : load(skip)           ; compute(skip)     ; store(row N-1)
  ROW_I:
    for (i = 0; i < ni + 2; i++) {
#pragma HLS LOOP_TRIPCOUNT min=NI+2 max=NI+2

      bool do_load    = (i < ni);
      bool do_compute = (i >= 1) && (i < ni + 1);
      bool do_store   = (i >= 2);

      int load_row    = i;       // row being loaded this iter
      int compute_row = i - 1;   // row being computed this iter
      int store_row   = i - 2;   // row being stored this iter

      // Buffer selection flags:
      //   load uses buffer (load_row % 2)
      //   compute uses buffer (compute_row % 2)
      //   store uses buffer (store_row % 2)
      bool load_buf    = (load_row    & 1);   // false -> set 1, true -> set 2
      bool compute_buf = (compute_row & 1);
      bool store_buf   = (store_row   & 1);

      // ---- LOAD phase: bring C row (scaled by beta) and A row into buffers ----
      if (do_load) {
        if (!load_buf) {
        LOAD_C_1:
          for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
            C_local_1[j] = C[load_row][j] * beta;
          }
        LOAD_A_1:
          for (k = 0; k < nk; k++) {
#pragma HLS LOOP_TRIPCOUNT min=NK max=NK
#pragma HLS PIPELINE II=1
            A_local_1[k] = A[load_row][k];
          }
        } else {
        LOAD_C_2:
          for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
            C_local_2[j] = C[load_row][j] * beta;
          }
        LOAD_A_2:
          for (k = 0; k < nk; k++) {
#pragma HLS LOOP_TRIPCOUNT min=NK max=NK
#pragma HLS PIPELINE II=1
            A_local_2[k] = A[load_row][k];
          }
        }
      }

      // ---- COMPUTE phase: GEMM from local buffers ----
      if (do_compute) {
        if (!compute_buf) {
        COMPUTE_K_1:
          for (k = 0; k < nk; k++) {
#pragma HLS LOOP_TRIPCOUNT min=NK max=NK
          COMPUTE_J_1:
            for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=2
#pragma HLS DEPENDENCE variable=C_local_1 inter false
              C_local_1[j] += alpha * A_local_1[k] * B_local[k][j];
            }
          }
        } else {
        COMPUTE_K_2:
          for (k = 0; k < nk; k++) {
#pragma HLS LOOP_TRIPCOUNT min=NK max=NK
          COMPUTE_J_2:
            for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=2
#pragma HLS DEPENDENCE variable=C_local_2 inter false
              C_local_2[j] += alpha * A_local_2[k] * B_local[k][j];
            }
          }
        }
      }

      // ---- STORE phase: write computed C row back to global memory ----
      if (do_store) {
        if (!store_buf) {
        STORE_C_1:
          for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
            C[store_row][j] = C_local_1[j];
          }
        } else {
        STORE_C_2:
          for (j = 0; j < nj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=NJ max=NJ
#pragma HLS PIPELINE II=1
            C[store_row][j] = C_local_2[j];
          }
        }
      }
    }

}
}
```

**Correctness reasoning:**

- The outer loop runs `ni + 2` iterations.
- **Load** happens for `i = 0 .. ni-1` (row `i` into buffer `i%2`).
- **Compute** happens for `i = 1 .. ni` (processing `compute_row = i-1`, i.e. rows `0 .. ni-1`), reading from buffer `(i-1)%2` — the exact buffer that was loaded one iteration earlier.
- **Store** happens for `i = 2 .. ni+1` (storing `store_row = i-2`, i.e. rows `0 .. ni-1`), reading from buffer `(i-2)%2` — the exact buffer that was computed one iteration earlier.

Each row's buffer selection (`row & 1`) is consistent across its load → compute → store lifetime, and consecutive rows use alternating buffers so load(row t) never overwrites compute(row t-1). This produces byte-identical output to the single-buffer version. Since only `A_local` and `C_local` are duplicated (small 1-D buffers), BRAM growth stays well within limits and DSP count is unchanged.

