        }
        if (buf_sel == 0) {
            for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
#pragma HLS DEPENDENCE variable=sum_acc inter false
                sum_acc[j] += row_buf_mean_0[j];
            }
        } else {
            for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
#pragma HLS DEPENDENCE variable=sum_acc inter false
                sum_acc[j] += row_buf_mean_1[j];
            }
        }
    }

    /* Finalize mean */
    for (int j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
        local_mean[j] = sum_acc[j] / float_n;
        mean[j] = local_mean[j];
    }

    /* Initialize stddev accumulators */
    for (int j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
        sum_acc[j] = 0.0;
    }

    /* Compute stddev - double-buffer row loads */
    double row_buf_std_0[M];
    double row_buf_std_1[M];
#pragma HLS ARRAY_PARTITION variable=row_buf_std_0 cyclic factor=8
#pragma HLS ARRAY_PARTITION variable=row_buf_std_1 cyclic factor=8

    // Prologue: load row 0
    for (int j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
        row_buf_std_0[j] = data[0][j];
    }

    for (int i = 0; i < n; i++)
    {
#pragma HLS LOOP_TRIPCOUNT min=100 max=100
        int buf_sel = i % 2;
        if (i + 1 < n) {
            if (buf_sel == 0) {
                for (int j = 0; j < m; j++)
                {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
                    row_buf_std_1[j] = data[i + 1][j];
                }
            } else {
                for (int j = 0; j < m; j++)
                {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
                    row_buf_std_0[j] = data[i + 1][j];
                }
            }
        }
        if (buf_sel == 0) {
            for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
#pragma HLS DEPENDENCE variable=sum_acc inter false
                double d = row_buf_std_0[j] - local_mean[j];
                sum_acc[j] += d * d;
            }
        } else {
            for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
#pragma HLS DEPENDENCE variable=sum_acc inter false
                double d = row_buf_std_1[j] - local_mean[j];
                sum_acc[j] += d * d;
            }
        }
    }

    /* Finalize stddev */
    for (int j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
        double s = sqrt(sum_acc[j] / float_n);
        s = (s <= eps) ? 1.0 : s;
        local_stddev[j] = s;
        stddev[j] = s;
    }

    /* Center and normalize data - row by row for coalesced access */
    double inv_sqrt_n = 1.0 / sqrt(float_n);

    // Precompute normalization factors
    double norm_factor[M];
#pragma HLS ARRAY_PARTITION variable=norm_factor cyclic factor=8
    for (int j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
        norm_factor[j] = inv_sqrt_n * local_stddev[j];
    }

    for (int i = 0; i < n; i++)
    {
#pragma HLS LOOP_TRIPCOUNT min=100 max=100
        double row_buf[M];
#pragma HLS ARRAY_PARTITION variable=row_buf cyclic factor=8
        for (int j = 0; j < m; j++)
        {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
            row_buf[j] = data[i][j];
        }
        for (int j = 0; j < m; j++)
        {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
#pragma HLS DEPENDENCE variable=row_buf inter false
            row_buf[j] = (row_buf[j] - local_mean[j]) / norm_factor[j];
        }
        for (int j = 0; j < m; j++)
        {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
            data[i][j] = row_buf[j];
        }
    }

    /* Load all normalized data into local 2D buffer */
    double data_local[N][M];
#pragma HLS ARRAY_PARTITION variable=data_local cyclic factor=8 dim=2

    for (int i = 0; i < n; i++)
    {
#pragma HLS LOOP_TRIPCOUNT min=100 max=100
        for (int j = 0; j < m; j++)
        {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
            data_local[i][j] = data[i][j];
        }
    }

    /* Compute correlation matrix using tiled dot products */
    // Tile size for accumulation to hide FP latency (power of 2 for mask trick)
    static const int TILE = 8;

    for (int i = 0; i < m - 1; i++)
    {
#pragma HLS LOOP_TRIPCOUNT min=79 max=79
        corr[i][i] = 1.0;

        // Load column i into local buffer
        double col_i[N];
#pragma HLS ARRAY_PARTITION variable=col_i cyclic factor=8
        for (int k = 0; k < n; k++)
        {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=100 max=100
            col_i[k] = data_local[k][i];
        }

        // Process columns j = i+1 .. m-1
        for (int j = i + 1; j < m; j++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=79
            // Load column j into local buffer
            double col_j[N];
#pragma HLS ARRAY_PARTITION variable=col_j cyclic factor=8
            for (int k = 0; k < n; k++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=100 max=100
                col_j[k] = data_local[k][j];
            }

            // Accumulate dot product using a tiled accumulator array
            // to break the FP loop-carried dependency
            double acc[TILE];
#pragma HLS ARRAY_PARTITION variable=acc complete
            for (int t = 0; t < TILE; t++)
            {
#pragma HLS UNROLL
                acc[t] = 0.0;
            }

            // Main dot product loop with explicit bit-mask indexing
            // so HLS sees distinct accumulator elements (no modulo ambiguity)
            int n_full = (n / TILE) * TILE;
            for (int k = 0; k < n_full; k += TILE)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=12 max=12
                acc[0] += col_i[k+0] * col_j[k+0];
                acc[1] += col_i[k+1] * col_j[k+1];
                acc[2] += col_i[k+2] * col_j[k+2];
                acc[3] += col_i[k+3] * col_j[k+3];
                acc[4] += col_i[k+4] * col_j[k+4];
                acc[5] += col_i[k+5] * col_j[k+5];
                acc[6] += col_i[k+6] * col_j[k+6];
                acc[7] += col_i[k+7] * col_j[k+7];
            }
            // Handle remainder
            for (int k = n_full; k < n; k++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=7
                acc[k & (TILE-1)] += col_i[k] * col_j[k];
            }

            // Reduce accumulator
            double sum = 0.0;
            for (int t = 0; t < TILE; t++)
            {
#pragma HLS UNROLL
                sum += acc[t];
            }

            corr[i][j] = sum;
            corr[j][i] = sum;
        }
    }
    corr[m - 1][m - 1] = 1.0;
}

} // extern "C"
```

