#include "cholesky.h"

static const int TILE_SIZE = 64;

static void load(
    double A[N + 0][N + 0],
    int row_idx,
    bool flag,
    bool valid,
    double row_i_1[N],
    double row_i_2[N])
{
#pragma HLS INLINE

    if (valid) {
        if (!flag) {
            /*
             * Tiled load phase: stage the active input row from AXI memory
             * into a local row buffer before compute uses it.
             */
            for (int base = 0; base < N; base += TILE_SIZE) {
                for (int jj = 0; jj < TILE_SIZE; jj++) {
#pragma HLS PIPELINE II=1
                    int j = base + jj;
                    if (j <= row_idx && j < N) {
                        row_i_1[j] = A[row_idx][j];
                    }
                }
            }
        } else {
            /*
             * Tiled load phase into the alternate local row buffer.
             */
            for (int base = 0; base < N; base += TILE_SIZE) {
                for (int jj = 0; jj < TILE_SIZE; jj++) {
#pragma HLS PIPELINE II=1
                    int j = base + jj;
                    if (j <= row_idx && j < N) {
                        row_i_2[j] = A[row_idx][j];
                    }
                }
            }
        }
    }
}

static void compute_body(
    double A[N + 0][N + 0],
    int i,
    double row_i[N],
    double row_j[N],
    double row_out[N],
    double prev_row_out[N])
{
#pragma HLS INLINE

    /*
     * Local compute/output initialization phase.
     * Copy the tiled-loaded active row into the local output buffer.
     */
    for (int base = 0; base < N; base += TILE_SIZE) {
        for (int jj = 0; jj < TILE_SIZE; jj++) {
#pragma HLS PIPELINE II=1
            int j = base + jj;
            if (j <= i && j < N) {
                row_out[j] = row_i[j];
            }
        }
    }

    for (int j = 0; j < i; j++) {

        /*
         * Tiled load phase for the previous factor row.
         * The arithmetic below only consumes row_j[] / row_out[] local buffers,
         * avoiding direct AXI accesses in the compute loop.
         */
        if (j == i - 1) {
            for (int base = 0; base < N; base += TILE_SIZE) {
                for (int kk = 0; kk < TILE_SIZE; kk++) {
#pragma HLS PIPELINE II=1
                    int k = base + kk;
                    if (k <= j && k < N) {
                        row_j[k] = prev_row_out[k];
                    }
                }
            }
        } else {
            for (int base = 0; base < N; base += TILE_SIZE) {
                for (int kk = 0; kk < TILE_SIZE; kk++) {
#pragma HLS PIPELINE II=1
                    int k = base + kk;
                    if (k <= j && k < N) {
                        row_j[k] = A[j][k];
                    }
                }
            }
        }

        /*
         * Compute phase on local buffers.
         * Use a scalar accumulator to avoid repeated read/write updates to
         * row_out[j] inside the recurrence.
         */
        double acc = row_out[j];
        for (int k = 0; k < j; k++) {
#pragma HLS UNROLL factor=2
            acc -= row_out[k] * row_j[k];
        }

        row_out[j] = acc / row_j[j];
    }

    /*
     * Final diagonal update, computed entirely from the local row_out buffer.
     */
    double diag_acc = row_out[i];
    for (int k = 0; k < i; k++) {
#pragma HLS UNROLL factor=2
        diag_acc -= row_out[k] * row_out[k];
    }

    row_out[i] = sqrt(diag_acc);
}

static void compute(
    double A[N + 0][N + 0],
    int row_idx,
    bool flag,
    bool valid,
    double row_i_1[N],
    double row_i_2[N],
    double row_j_1[N],
    double row_j_2[N],
    double row_out_1[N],
    double row_out_2[N])
{
#pragma HLS INLINE

    if (valid) {
        if (!flag) {
            compute_body(A, row_idx, row_i_1, row_j_1, row_out_1, row_out_2);
        } else {
            compute_body(A, row_idx, row_i_2, row_j_2, row_out_2, row_out_1);
        }
    }
}

static void store(
    double A[N + 0][N + 0],
    int row_idx,
    bool flag,
    bool valid,
    double row_out_1[N],
    double row_out_2[N])
{
#pragma HLS INLINE

    if (valid) {
        if (!flag) {
            /*
             * Tiled store phase: write the completed local output row back to AXI.
             */
            for (int base = 0; base < N; base += TILE_SIZE) {
                for (int jj = 0; jj < TILE_SIZE; jj++) {
#pragma HLS PIPELINE II=1
                    int j = base + jj;
                    if (j <= row_idx && j < N) {
                        A[row_idx][j] = row_out_1[j];
                    }
                }
            }
        } else {
            /*
             * Tiled store phase from the alternate local output row.
             */
            for (int base = 0; base < N; base += TILE_SIZE) {
                for (int jj = 0; jj < TILE_SIZE; jj++) {
#pragma HLS PIPELINE II=1
                    int j = base + jj;
                    if (j <= row_idx && j < N) {
                        A[row_idx][j] = row_out_2[j];
                    }
                }
            }
        }
    }
}

extern "C" {

void kernel_cholesky(double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem depth=14400 max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    double row_i_1[N];
    double row_i_2[N];
    double row_j_1[N];
    double row_j_2[N];

    /*
     * Local output buffers hold completed rows until their delayed store phase.
     */
    double row_out_1[N];
    double row_out_2[N];

#pragma HLS ARRAY_PARTITION variable=row_i_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_i_2 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_2 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_out_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_out_2 cyclic factor=2 dim=1

    /*
     * Load / compute / store tiled row schedule.
     *
     * iter 0    : load row 0        ; compute skip       ; store skip
     * iter 1    : load row 1        ; compute row 0      ; store skip
     * iter 2    : load row 2        ; compute row 1      ; store row 0
     * ...
     * iter N    : load skip         ; compute row N-1    ; store row N-2
     * iter N+1  : load skip         ; compute skip       ; store row N-1
     */
    for (int iter = 0; iter < n + 2; iter++) {

        const bool load_valid = (iter < n);
        const int load_idx = iter;
        const bool load_flag = load_valid ? ((load_idx & 1) != 0) : false;

        const bool compute_valid = (iter >= 1 && iter <= n);
        const int compute_idx = iter - 1;
        const bool compute_flag = compute_valid ? ((compute_idx & 1) != 0) : false;

        const bool store_valid = (iter >= 2 && iter < n + 2);
        const int store_idx = iter - 2;
        const bool store_flag = store_valid ? ((store_idx & 1) != 0) : false;

        load(A, load_idx, load_flag, load_valid, row_i_1, row_i_2);

        compute(A,
                compute_idx,
                compute_flag,
                compute_valid,
                row_i_1,
                row_i_2,
                row_j_1,
                row_j_2,
                row_out_1,
                row_out_2);

        store(A, store_idx, store_flag, store_valid, row_out_1, row_out_2);
    }
}

}

