                        A[row_idx][j] = row_out_2[j];
                    }
                }
            }
        }
    }
}

extern "C" {

void kernel_cholesky(double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem depth=14400 max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    double row_i_1[N];
    double row_i_2[N];
    double row_j_1[N];
    double row_j_2[N];

    /*
     * Local output buffers hold completed rows until their delayed store phase.
     */
    double row_out_1[N];
    double row_out_2[N];

#pragma HLS ARRAY_PARTITION variable=row_i_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_i_2 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_2 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_out_1 cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=row_out_2 cyclic factor=2 dim=1

    /*
     * Load / compute / store tiled row schedule.
     *
     * iter 0    : load row 0        ; compute skip       ; store skip
     * iter 1    : load row 1        ; compute row 0      ; store skip
     * iter 2    : load row 2        ; compute row 1      ; store row 0
     * ...
     * iter N    : load skip         ; compute row N-1    ; store row N-2
     * iter N+1  : load skip         ; compute skip       ; store row N-1
     */
    for (int iter = 0; iter < n + 2; iter++) {

        const bool load_valid = (iter < n);
        const int load_idx = iter;
        const bool load_flag = load_valid ? ((load_idx & 1) != 0) : false;

        const bool compute_valid = (iter >= 1 && iter <= n);
        const int compute_idx = iter - 1;
        const bool compute_flag = compute_valid ? ((compute_idx & 1) != 0) : false;

        const bool store_valid = (iter >= 2 && iter < n + 2);
        const int store_idx = iter - 2;
        const bool store_flag = store_valid ? ((store_idx & 1) != 0) : false;

        load(A, load_idx, load_flag, load_valid, row_i_1, row_i_2);

        compute(A,
                compute_idx,
                compute_flag,
                compute_valid,
                row_i_1,
                row_i_2,
                row_j_1,
                row_j_2,
                row_out_1,
                row_out_2);

        store(A, store_idx, store_flag, store_valid, row_out_1, row_out_2);
    }
}

}
