Looking at this GEMM kernel, I need to:

1. Add HLS interface pragmas for the top-level function
2. Stage inputs into local buffers (load-compute-store pattern)
3. Apply the GEMM flatten + k-partition pattern for the compute nest
4. Pipeline load/store loops and flatten the (i,j) compute nest with k fully unrolled

The working set: `C[60][70]` (33,600 bytes) + `A[60][80]` (38,400 bytes) + `B[80][70]` (44,800 bytes) ≈ 117KB total — fits in BRAM on UltraScale+.

For the GEMM nest: partition A on dim=2 (k), B on dim=1 (k), pipeline the (i,j) nest with LOOP_FLATTEN and UNROLL k.

```cpp
#include "gemm.h"

extern "C" {

void kernel_gemm(
    double alpha,
    double beta,
    double C[NI + 0][NJ + 0],
    double A[NI + 0][NK + 0],
    double B[NK + 0][NJ + 0])
{
#pragma HLS INTERFACE s_axilite port=return   bundle=control
#pragma HLS INTERFACE s_axilite port=alpha    bundle=control
#pragma HLS INTERFACE s_axilite port=beta     bundle=control
#pragma HLS INTERFACE m_axi     port=C        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=C        bundle=control
#pragma HLS INTERFACE m_axi     port=A        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A        bundle=control
#pragma HLS INTERFACE m_axi     port=B        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=B        bundle=control

    // Local on-chip buffers
    double local_C[NI][NJ];
    double local_A[NI][NK];
    double local_B[NK][NJ];

    // Partition for parallel k-dimension access in the GEMM compute
#pragma HLS ARRAY_PARTITION variable=local_A complete dim=2
#pragma HLS ARRAY_PARTITION variable=local_B complete dim=1

    // Load A
    load_A:
    for (int i = 0; i < NI; i++) {
        for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            local_A[i][k] = A[i][k];
        }
    }

    // Load B
    load_B:
    for (int k = 0; k < NK; k++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            local_B[k][j] = B[k][j];
        }
    }

    // Load C
    load_C:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            local_C[i][j] = C[i][j];
        }
    }

    // Scale C by beta, then accumulate alpha * A * B into C
    // Phase 1: C[i][j] *= beta
    scale_C:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
            local_C[i][j] *= beta;
        }
    }

    // Phase 2: C[i][j] += alpha * A[i][k] * B[k][j], fully unrolling k
    compute:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
            double sum = 0.0;
            for (int k = 0; k < NK; k++) {
#pragma HLS UNROLL
                sum += local_A[i][k] * local_B[k][j];
            }
            local_C[i][j] += alpha * sum;
        }
    }

    // Store C back
    store_C:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = local_C[i][j];
        }
    }
}

} // extern "C"
