#include "gemm.h"

extern "C" {

void kernel_gemm(
    double alpha,
    double beta,
    double C[NI + 0][NJ + 0],
    double A[NI + 0][NK + 0],
    double B[NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem \
    max_read_burst_length=64 max_write_burst_length=64 \
    num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem \
    max_read_burst_length=64 max_write_burst_length=64 \
    num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem \
    max_read_burst_length=64 max_write_burst_length=64 \
    num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    // Double-buffered local_C rows: buf 0 and buf 1
    // Each holds one row of C at a time; we alternate between them
    // so we can store one row while computing the next.
    double local_C_0[NJ];
    double local_C_1[NJ];
#pragma HLS ARRAY_PARTITION variable=local_C_0 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_C_1 cyclic factor=8 dim=1

    double local_A[NI][NK];
#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=8 dim=2

    double local_B[NK][NJ];
#pragma HLS ARRAY_PARTITION variable=local_B cyclic factor=8 dim=2

    // Load A — contiguous row-major burst from AXI
    load_A:
    for (int i = 0; i < ni; i++) {
        for (int k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
            local_A[i][k] = A[i][k];
        }
    }

    // Load B — contiguous row-major burst from AXI
    load_B:
    for (int k = 0; k < nk; k++) {
        for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            local_B[k][j] = B[k][j];
        }
    }

    // Double-buffered compute+store:
    // Prologue/epilogue pattern with NI+2 outer iterations:
    //   iter 0:        load C[0] into buf_0;  skip compute;    skip store
    //   iter 1:        load C[1] into buf_1;  compute row 0 in buf_0;  skip store
    //   iter 2..NI:    load C[i] into buf_X;  compute row i-1 in buf_Y;  store row i-2
    //   iter NI:       load C[NI-1]; compute row NI-2; store row NI-3
    //   iter NI+1:     skip load;  skip compute;  store row NI-1  (but we need one more)
    // 
    // Simpler and more correct: process row by row with double buffering
    // so that store of row i-1 overlaps with compute of row i.
    // We use a flag to select between buf_0 and buf_1.

    // Process NI+1 iterations to pipeline load/compute/store:
    // iter i (0-based):
    //   load:    if i < NI: load C row i into buf[i%2]
    //   compute: if i >= 1 && i <= NI: compute row i-1 using buf[(i-1)%2]
    //   store:   if i >= 2: store row i-2 from buf[(i-2)%2]  -- but buf was overwritten!
    //
    // Actually for correct double buffering we need N+1 iterations where:
    //   iter i (0..NI):
    //     load:    if i < NI: load C[i] into buf[i%2]
    //     compute: if i > 0:  compute row i-1 using buf[(i-1)%2]
    //     store:   if i > 0:  store C[i-1] from result in buf[(i-1)%2]
    //
    // But load and compute of same buf[(i-1)%2] conflict at iter i when
    // (i%2) == ((i-1)%2), which never happens. So this is safe.

    for (int i = 0; i <= ni; i++) {
        // SELECT which buffer to use for load (current) and compute (previous)
        int load_buf  = i % 2;       // buf for row i
        int comp_buf  = (i + 1) % 2; // buf for row i-1 (== (i-1)%2)

        // --- LOAD phase: load C row i into the load buffer ---
        if (i < ni) {
            if (load_buf == 0) {
                load_C_row_0:
                for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                    local_C_0[j] = C[i][j];
                }
            } else {
                load_C_row_1:
                for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                    local_C_1[j] = C[i][j];
                }
            }
        }

        // --- COMPUTE phase: compute row i-1 from the compute buffer ---
        if (i > 0) {
            int ci = i - 1; // row being computed
            if (comp_buf == 0) {
                // Scale by beta
                scale_beta_0:
                for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
                    local_C_0[j] *= beta;
                }
                // Accumulate alpha * A * B
                accum_0:
                for (int k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=local_C_0 inter RAW false
#pragma HLS DEPENDENCE variable=local_C_0 intra RAW false
                    double alpha_a = alpha * local_A[ci][k];
                    for (int j = 0; j < nj; j++) {
#pragma HLS UNROLL factor=8
                        local_C_0[j] += alpha_a * local_B[k][j];
                    }
                }
                // Store row ci back to global C
                store_C_row_0:
                for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                    C[ci][j] = local_C_0[j];
                }
            } else {
                // Scale by beta
                scale_beta_1:
                for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
                    local_C_1[j] *= beta;
                }
                // Accumulate alpha * A * B
                accum_1:
                for (int k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=local_C_1 inter RAW false
#pragma HLS DEPENDENCE variable=local_C_1 intra RAW false
                    double alpha_a = alpha * local_A[ci][k];
                    for (int j = 0; j < nj; j++) {
#pragma HLS UNROLL factor=8
                        local_C_1[j] += alpha_a * local_B[k][j];
                    }
                }
                // Store row ci back to global C
                store_C_row_1:
                for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                    C[ci][j] = local_C_1[j];
                }
            }
        }
    }
}

} // extern "C"

